// ecdh-secp256k1.mjs — drop-in polyfill untuk crypto.createECDH("secp256k1")
// Runtime tertentu (mis. Bun ≤1.3.x) tidak menyediakan kurva secp256k1 pada
// createECDH dan melempar "Failed to create key using named curve".
// CLI baw hanya butuh: generateKeys() → getPrivateKey() → getPublicKey("hex","compressed").
// Implementasi: aritmetika titik kurva y² = x³ + 7 (mod p) dengan BigInt murni.
import { randomBytes, createECDH as nativeCreateECDH } from "node:crypto";

const P = 0xfffffffffffffffffffffffffffffffffffffffffffffffffffffffefffffc2fn;
const N = 0xfffffffffffffffffffffffffffffffebaaedce6af48a03bbfd25e8cd0364141n;
const GX = 0x79be667ef9dcbbac55a06295ce870b07029bfcdb2dce28d959f2815b16f81798n;
const GY = 0x483ada7726a3c4655da4fbfc0e1108a8fd17b448a68554199c47d08ffb10d4b8n;
const B = 7n;

const mod = (a) => {
  const r = a % P;
  return r >= 0n ? r : r + P;
};
const modInv = (a) => {
  let [lr, r] = [mod(a), P];
  let [ls, s] = [1n, 0n];
  while (r !== 0n) {
    const q = lr / r;
    [lr, r] = [r, lr - q * r];
    [ls, s] = [s, ls - q * s];
  }
  return mod(ls);
};
const modPow = (base, exp) => {
  let result = 1n;
  let b = mod(base);
  let e = exp;
  while (e > 0n) {
    if (e & 1n) result = mod(result * b);
    b = mod(b * b);
    e >>= 1n;
  }
  return result;
};
const onCurve = (x, y) => mod(y * y) === mod(x * x * x + B);

// Titik dalam koordinat affine [x, y] | null (null = titik di tak hingga)
function pointAdd(p1, p2) {
  if (!p1) return p2;
  if (!p2) return p1;
  const [x1, y1] = p1;
  const [x2, y2] = p2;
  if (x1 === x2) {
    if (mod(y1 + y2) === 0n) return null;
    return pointDouble(p1);
  }
  const s = mod((y2 - y1) * modInv(mod(x2 - x1 + P)));
  const x3 = mod(s * s - x1 - x2);
  const y3 = mod(s * (x1 - x3) - y1);
  return [x3, y3];
}
function pointDouble(p) {
  if (!p) return null;
  const [x, y] = p;
  if (y === 0n) return null;
  const s = mod(3n * x * x * modInv(2n * y));
  const x3 = mod(s * s - 2n * x);
  const y3 = mod(s * (x - x3) - y);
  return [x3, y3];
}
function scalarMult(k, point) {
  let acc = null;
  let add = point;
  while (k > 0n) {
    if (k & 1n) acc = pointAdd(acc, add);
    add = pointDouble(add);
    k >>= 1n;
  }
  return acc;
}
const pointToBuffers = (pt) => {
  if (!pt) throw new Error("point at infinity");
  const [x, y] = pt;
  const xb = Buffer.from(x.toString(16).padStart(64, "0"), "hex");
  const yb = Buffer.from(y.toString(16).padStart(64, "0"), "hex");
  return { uncompressed: Buffer.concat([Buffer.from([0x04]), xb, yb]), compressed: Buffer.concat([Buffer.from([0x02 | Number(y & 1n)]), xb]) };
};
function pointFromBuffer(buf) {
  if (buf.length === 33 && (buf[0] === 0x02 || buf[0] === 0x03)) {
    const x = BigInt("0x" + buf.subarray(1).toString("hex"));
    // y = sqrt(x³+7) → eksponensiasi p+1/4 (p ≡ 3 mod 4)
    const a = mod(x * x * x + B);
    let y = modPow(a, (P + 1n) / 4n);
    if (mod(y * y) !== a) throw new Error("invalid point (not on curve)");
    if ((y & 1n) !== BigInt(buf[0] & 1)) y = P - y;
    return [x, y];
  }
  if (buf.length === 65 && buf[0] === 0x04) {
    const x = BigInt("0x" + buf.subarray(1, 33).toString("hex"));
    const y = BigInt("0x" + buf.subarray(33).toString("hex"));
    if (!onCurve(x, y)) throw new Error("invalid point (not on curve)");
    return [x, y];
  }
  throw new Error(`unsupported public key format (len=${buf.length})`);
}
const encToBuf = (v, enc) =>
  v instanceof Buffer ? v : typeof v === "string" ? Buffer.from(v, enc || "hex") : Buffer.from(v);

class Secp256k1ECDH {
  constructor() {
    this.priv = null;
    this.pub = null; // [x, y]
  }
  generateKeys(_enc, _format) {
    do {
      this.priv = BigInt("0x" + randomBytes(32).toString("hex"));
    } while (this.priv === 0n || this.priv >= N);
    this.pub = scalarMult(this.priv, [GX, GY]);
    return this.getPublicKey(_enc, _format);
  }
  getPrivateKey(enc) {
    if (!this.priv) throw new Error("ECDH not initialized — call generateKeys() first");
    const buf = Buffer.from(this.priv.toString(16).padStart(64, "0"), "hex");
    return enc ? buf.toString(enc) : buf;
  }
  getPublicKey(enc, format) {
    if (!this.pub) throw new Error("ECDH not initialized — call generateKeys() first");
    const { uncompressed, compressed } = pointToBuffers(this.pub);
    const buf = format === "compressed" ? compressed : uncompressed;
    return enc ? buf.toString(enc) : buf;
  }
  computeSecret(key, inEnc, outEnc) {
    const peer = pointFromBuffer(encToBuf(key, inEnc));
    const shared = scalarMult(this.priv, peer);
    if (!shared) throw new Error("shared secret is point at infinity");
    const x = Buffer.from(shared[0].toString(16).padStart(64, "0"), "hex");
    return outEnc ? x.toString(outEnc) : x;
  }
  setPrivateKey() {
    throw new Error("setPrivateKey not supported by secp256k1 polyfill");
  }
}

export function createECDH(curve) {
  if (curve === "secp256k1") return new Secp256k1ECDH();
  // Kurva lain → runtime asli (P-256 dll. didukung Bun/Node)
  return nativeCreateECDH(curve);
}
